class DirectGitRunner {
    cwd;
    constructor(cwd) {
        this.cwd = cwd;
    }
    async run(args, timeout) {
        const { stdout } = await execFileAsync('git', [...args], {
            cwd: this.cwd,
            timeout,
            maxBuffer: GIT_MAX_OUTPUT_BYTES,
            encoding: 'utf8',
            windowsHide: true,
            shell: false,
            env: createGitEnvironment(),
        });
        return { stdout };
    }
    async close() {
        // Direct commands have no session process to release.
    }
}

